// The contract with both callers, enforced here rather than trusted.
// Anything downstream that reads a field this node did not set is a bug.
const crypto = require('crypto');

const input = $input.first().json ?? {};

const channel = String(input.channel || '').trim();
if (channel !== 'email' && channel !== 'chat') {
  throw new Error('channel must be "email" or "chat", got: ' + JSON.stringify(input.channel));
}

const text = String(input.text || '').trim();
if (!text) throw new Error('the answer engine was called with an empty question');

const conversationRef = String(input.session_or_thread_id || '').trim();
if (!conversationRef) throw new Error('session_or_thread_id is required so the answer can be traced back');

// History arrives oldest-first and is only ever used as context for the model.
// It is capped here because a long transcript pushes the retrieved passages out
// of the model's attention, which is the opposite of what it is for.
const history = (Array.isArray(input.history) ? input.history : [])
  .filter((turn) => turn && turn.content)
  .slice(-12)
  .map((turn) => ({
    role: turn.role === 'agent' || turn.role === 'assistant' ? 'agent' : 'visitor',
    content: String(turn.content).slice(0, 1500),
  }));

// The retrieval query is not the raw email. Quoted reply blocks, signatures and
// disclaimers are most of the text in a threaded email and none of the meaning;
// left in, they match every article that mentions "regards" and rank the real
// answer below the noise.
const retrievalQuery = text
  .split(/\n\s*(?:On .*wrote:|-{2,}\s*Original Message|_{5,}|--\s*$)/m)[0]
  .split(/\n\s*>/)[0]
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 400);

// A follow-up question is short and pronoun-shaped: "and what does that cost?"
// shares no word with any article, so retrieval on its own finds nothing and the
// desk looks like it has forgotten the conversation it is in. Expanding the
// query with the visitor's PREVIOUS message is what makes the second question in
// a thread findable at all.
//
// Only the previous visitor turn, never the agent's reply: the agent's reply was
// written out of an article, so feeding it back in retrieves that same article
// whatever was actually asked next.
const lastVisitorTurn = [...history].reverse().find((t) => t.role === 'visitor');
const expandedQuery = (lastVisitorTurn ? retrievalQuery + ' ' + lastVisitorTurn.content : retrievalQuery)
  .replace(/s+/g, ' ')
  .trim()
  .slice(0, 600);

const normalisedQuestion = retrievalQuery.toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();

return [
  {
    json: {
      channel,
      question: text.slice(0, 4000),
      retrieval_query: expandedQuery,
      retrieval_query_own_words: retrievalQuery,
      question_hash: crypto.createHash('sha256').update(normalisedQuestion).digest('hex'),
      conversation_ref: conversationRef,
      history,
      history_turns: history.length,
    },
  },
];

// Zero rows is a state, not silence. `alwaysOutputData` on the node above means
// a question that matched nothing still arrives here as one empty item, so the
// IF below can route it instead of the branch quietly ending.
const floor = Number($env.KB_RELEVANCE_FLOOR || 0);
const request = $('Normalise Request').first().json;

const rows = $input.all().map((i) => i.json).filter((r) => r && r.id !== undefined);
const kept = rows.filter((r) => Number(r.relevance) >= floor);

const passages = kept.map((r) => ({
  id: Number(r.id),
  slug: r.slug,
  title: r.title,
  passage: r.passage,
  relevance: Number(r.relevance),
}));

return [
  {
    json: {
      ...request,
      passages,
      retrieved_count: rows.length,
      kept_count: passages.length,
      top_relevance: passages.length ? passages[0].relevance : 0,
      relevance_floor: floor,
      has_context: passages.length > 0,
    },
  },
];

