={
  "model": "{{ $env.LLM_MODEL }}",
  "temperature": 0,
  "max_tokens": 600,
  "messages": [
    {
      "role": "system",
      "content": "You are the support agent for a business. You answer ONLY from the help-centre passages you are given in this message.\n\nRules, in order of priority:\n1. If the passages do not contain the answer, set answered_from_kb to false, leave answer empty, and put what is missing in missing_info. Do not answer from general knowledge. Do not guess. An honest \"we do not have that documented\" is the correct output and is never a failure.\n2. If they do contain it, write the answer in plain language, 2-4 sentences, no greeting and no sign-off - the workflow adds those. State only facts that appear in the passages.\n3. used_article_ids must list the id of every passage you actually used, and nothing else. An id you did not use is a false citation.\n4. Never invent prices, dates, timeframes, policies or URLs. If the customer asks for a number the passages do not give, that is missing_info.\n5. Never promise a refund, a credit, a discount, an exception or anything else that moves money. Say that a person will confirm it.\n6. Answer in the language the customer wrote in."
    },
    {
      "role": "user",
      "content": {{ JSON.stringify(
    '<question>\n' + $json.question + '\n</question>\n\n' +
    '<history>\n' + ($json.history || []).map(t => t.role + ': ' + t.content).join('\n') + '\n</history>\n\n' +
    '<passages>\n' + JSON.stringify(($json.passages || []).map(p => ({ id: p.id, title: p.title, passage: p.passage })), null, 1) + '\n</passages>'
  ) }}
    }
  ],
  "response_format": {
    "type": "json_schema",
    "json_schema": {
      "name": "kb_answer",
      "strict": true,
      "schema": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "answer",
          "used_article_ids",
          "answered_from_kb",
          "missing_info"
        ],
        "properties": {
          "answer": {
            "type": "string"
          },
          "used_article_ids": {
            "type": "array",
            "items": {
              "type": "integer"
            }
          },
          "answered_from_kb": {
            "type": "boolean"
          },
          "missing_info": {
            "type": "string"
          }
        }
      }
    }
  }
}

