// A strict json_schema response is a contract the provider enforces, not one we
// can assume held: a proxy, a rate limiter or an outage can put something else
// entirely in the body. Parsing defensively here is what turns "the model went
// weird" into a failed execution with a readable reason.
const context = $('Apply Relevance Floor').first().json;
const raw = $input.first().json;

const content = raw?.choices?.[0]?.message?.content;
if (typeof content !== 'string') {
  throw new Error(
    'The model endpoint did not return a chat completion. Body began: ' +
      JSON.stringify(raw).slice(0, 300),
  );
}

let parsed;
try {
  parsed = JSON.parse(content);
} catch (err) {
  throw new Error('The model returned content that is not JSON: ' + content.slice(0, 300));
}

const retrievedIds = (context.passages || []).map((p) => p.id);

// The one rule the prompt cannot be trusted to keep. An id the model cited that
// was never retrieved is dropped, and an answer left with no citation at all is
// not grounded regardless of what the model said about itself.
const citedIds = Array.isArray(parsed.used_article_ids) ? parsed.used_article_ids.map(Number) : [];
const usedIds = citedIds.filter((articleId) => retrievedIds.includes(articleId));
const hallucinatedIds = citedIds.filter((articleId) => !retrievedIds.includes(articleId));

const answerText = String(parsed.answer || '').trim();
const grounded = parsed.answered_from_kb === true && answerText.length > 0 && usedIds.length > 0;

// Confidence is NOT the model's opinion of its own answer - a model asked to
// score itself says 0.9 to anything. It is built from what the workflow can
// observe: how strongly the article it actually used matched the question.
// 0.45 is a solid single-article ts_rank on the seeded corpus - measured, not
// guessed: a real match there scores 0.24 to 0.70 and incidental overlap scores
// 0.04. Anything at or above 0.45 is treated as full retrieval confidence, and
// a half-match lands around 0.75, just above the default gate. Re-measure this
// against the client's own articles; it is corpus-specific.
const usedRelevance = Math.max(
  0,
  ...(context.passages || []).filter((p) => usedIds.includes(p.id)).map((p) => p.relevance),
);
const retrievalScore = Math.min(1, usedRelevance / 0.45);
const confidence = grounded ? Math.round((0.55 + 0.4 * retrievalScore) * 1000) / 1000 : 0;

return [
  {
    json: {
      ...context,
      grounded,
      answer: grounded ? answerText : null,
      confidence,
      used_article_ids: usedIds,
      hallucinated_article_ids: hallucinatedIds,
      model_said_answered: parsed.answered_from_kb === true,
      missing_info: String(parsed.missing_info || '').slice(0, 500),
      used_relevance: usedRelevance,
    },
  },
];

// The contract returned to whichever workflow called this one.
const r = $input.first().json;
return [
  {
    json: {
      grounded: true,
      answer: r.answer,
      confidence: r.confidence,
      used_article_ids: r.used_article_ids,
      escalate_reason: null,
      channel: r.channel,
      question: r.question,
      conversation_ref: r.conversation_ref,
      question_hash: r.question_hash,
      retrieved_count: r.retrieved_count,
      top_relevance: r.top_relevance,
      integration_error: null,
    },
  },
];

// Retrieval returned nothing above KB_RELEVANCE_FLOOR. The business has not
// written this article yet. That is worth knowing, so it is recorded rather
// than logged and forgotten.
const r = $input.first().json;
return [
  {
    json: {
      grounded: false,
      answer: null,
      confidence: 0,
      used_article_ids: [],
      escalate_reason: 'no_matching_article',
      channel: r.channel,
      question: r.question,
      conversation_ref: r.conversation_ref,
      question_hash: r.question_hash,
      retrieved_count: r.retrieved_count,
      top_relevance: r.top_relevance,
      missing_info: 'No help-centre article matched this question above the relevance floor.',
      integration_error: null,
    },
  },
];

// Articles were retrieved, and none of them contained the answer. A subtler gap
// than "nothing matched": the topic exists in the help centre but this specific
// question is not covered by it.
const r = $input.first().json;
return [
  {
    json: {
      grounded: false,
      answer: null,
      confidence: 0,
      used_article_ids: [],
      escalate_reason: 'not_answerable_from_kb',
      channel: r.channel,
      question: r.question,
      conversation_ref: r.conversation_ref,
      question_hash: r.question_hash,
      retrieved_count: r.retrieved_count,
      top_relevance: r.top_relevance,
      missing_info: r.missing_info || 'The retrieved articles do not cover this question.',
      integration_error: null,
    },
  },
];

// The model endpoint failed all three attempts. The engine returns "not
// grounded" rather than throwing, so the caller's own confidence gate turns an
// outage into a human handover instead of into a failed execution and a silent
// customer. The reason is different from a knowledge gap, and is kept different
// all the way into the decision log.
const context = $('Apply Relevance Floor').first().json;
const failure = $input.first().json?.error ?? {};

return [
  {
    json: {
      grounded: false,
      answer: null,
      confidence: 0,
      used_article_ids: [],
      escalate_reason: 'answer_engine_unavailable',
      channel: context.channel,
      question: context.question,
      conversation_ref: context.conversation_ref,
      question_hash: context.question_hash,
      retrieved_count: context.retrieved_count,
      top_relevance: context.top_relevance,
      missing_info: null,
      integration_error: String(failure.message || failure.description || 'model endpoint unavailable').slice(0, 400),
    },
  },
];

// One named upstream for the three ways an answer can fail to be grounded, so
// the nodes below can be written once instead of three times.
return $input.all();

// Both branches leave through here, so Execute Workflow always hands the caller
// the same shape whatever happened inside.
const item = $input.first().json ?? {};

// The grounded branch arrives carrying the contract already.
if (item.grounded === true) return [{ json: item }];

// The ungrounded branch arrives carrying the unanswered_questions row instead,
// so the contract is rebuilt from the junction node above.
const base = $('Ungrounded Result').first().json;
return [
  {
    json: {
      ...base,
      unanswered_question_id: item.id ?? null,
      times_asked: item.asked_count ?? null,
    },
  },
];
